const WHATSAPP_VERIFY_TOKEN = 'PASTE_WHATSAPP_VERIFY_TOKEN_HERE';

// n8n Cloud Starter has no Variables and blocks $env, so secrets are pasted
// into this node after import (replace the PASTE_... value below). On plans
// with Variables, or self-hosted with $env allowed, a variable of the same
// name wins and the pasted value can stay as the placeholder.
// Never commit a real secret back to GitHub: keep the placeholder in the repo.
function setting(name, pasted) {
  try { if ($vars && $vars[name]) return String($vars[name]); } catch (e) {}
  try { if ($env && $env[name]) return String($env[name]); } catch (e) {}
  return String(pasted || '').startsWith('PASTE_') ? '' : String(pasted || '');
}

// Meta's verification handshake: GET ?hub.mode=subscribe&hub.verify_token=...&hub.challenge=...
// Query params with dots arrive as literal keys (not nested objects) on n8n's webhook node.
const q = $json.query || {};
const expected = setting('WHATSAPP_VERIFY_TOKEN', WHATSAPP_VERIFY_TOKEN);
const ok = q['hub.mode'] === 'subscribe' && !!expected && q['hub.verify_token'] === expected;
return [{ json: { ok, challenge: q['hub.challenge'] || '' } }];

const META_APP_SECRET = 'PASTE_META_APP_SECRET_HERE';

// n8n Cloud Starter has no Variables and blocks $env, so secrets are pasted
// into this node after import (replace the PASTE_... value below). On plans
// with Variables, or self-hosted with $env allowed, a variable of the same
// name wins and the pasted value can stay as the placeholder.
// Never commit a real secret back to GitHub: keep the placeholder in the repo.
function setting(name, pasted) {
  try { if ($vars && $vars[name]) return String($vars[name]); } catch (e) {}
  try { if ($env && $env[name]) return String($env[name]); } catch (e) {}
  return String(pasted || '').startsWith('PASTE_') ? '' : String(pasted || '');
}

// Meta signs every webhook POST with X-Hub-Signature-256: an HMAC-SHA256 of
// the RAW request body, keyed with the Meta App Secret (Meta App Dashboard ->
// App settings -> Basic). Without this check anyone who finds this URL can
// POST a forged "customer message".
//
// "Raw Body" is switched on in the WhatsApp Webhook (POST) node (already set
// in this export) -- that's what puts the exact bytes Meta signed in
// binary.data. require('crypto') works on n8n Cloud; self-hosted needs
// NODE_FUNCTION_ALLOW_BUILTIN=crypto.
//
// For local testing with hand-written payloads ONLY, a WHATSAPP_SIGNATURE_CHECK
// variable set to "off" skips the check. Never in production.
const crypto = require('crypto');
const item = $input.first();
const json = item.json;

if (setting('WHATSAPP_SIGNATURE_CHECK', 'on').toLowerCase() === 'off') {
  return [{ json: { ...json, _signature: 'skipped' } }];
}

const secret = setting('META_APP_SECRET', META_APP_SECRET);
const header = String((json.headers || {})['x-hub-signature-256'] || '');
if (!secret) return [{ json: { ...json, _signature: 'no_secret_configured' } }];
if (!header.startsWith('sha256=')) return [{ json: { ...json, _signature: 'missing' } }];
if (!item.binary || !item.binary.data) return [{ json: { ...json, _signature: 'no_raw_body' } }];

const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = Buffer.from(crypto.createHmac('sha256', secret).update(raw).digest('hex'), 'utf8');
const given = Buffer.from(header.slice('sha256='.length).toLowerCase(), 'utf8');
const valid = given.length === expected.length && crypto.timingSafeEqual(given, expected);

return [{ json: { ...json, _signature: valid ? 'valid' : 'invalid' } }];

// Meta's Cloud API webhook shape:
// { entry: [{ changes: [{ value: { metadata: { phone_number_id }, contacts: [{ profile: { name }, wa_id }], messages: [{ from, id, timestamp, type, text: { body } }] } }] }] }
// The SAME path also receives delivery/read "statuses" updates with no "messages" key at all --
// those aren't a customer message and are skipped, as are reactions.
// Text and button replies go to Elliot as they are. Elliot can't open media yet, so a photo,
// voice note, document or location becomes a short note ("[Sent a photo: caption]") and Elliot
// answers that sensibly (e.g. asks the client to type the question) instead of staying silent.
const body = $json.body || $json;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];

// 0048: what else was in this delivery.
//  - Meta later reports a message it accepted as FAILED (number not on
//    WhatsApp, 24-hour window closed, blocked...). That used to be dropped;
//    now it is recorded so the team sees the client never got it.
//  - Meta may put several messages in one delivery. This workflow answers the
//    first; any others are counted so they show up in the alerts instead of
//    vanishing.
const allValues = (body?.entry || []).flatMap((en) => (en?.changes || []).map((ch) => ch?.value).filter(Boolean));
const failed = allValues.flatMap((v) => (v.statuses || []).filter((s) => s && s.status === 'failed').map((s) => ({
  phone_number_id: v.metadata?.phone_number_id || '',
  recipient: s.recipient_id || '',
  wa_message_id: s.id || '',
  error: (() => { const er = (s.errors || [])[0] || {}; const t = er.title || er.message || (er.error_data && er.error_data.details) || 'not delivered'; return `${t}${er.code ? ` (code ${er.code})` : ''}`; })(),
})));
const extraMessages = Math.max(0, allValues.reduce((sum, v) => sum + ((v.messages || []).filter((m) => m && m.type !== 'reaction').length), 0) - 1);
const extras = { delivery_failures: failed, has_delivery_failures: failed.length > 0, extra_messages: extraMessages,
  extra_phone_number_id: allValues[0]?.metadata?.phone_number_id || '' };

if (!value || !message) {
  return [{ json: { skip: true, reason: !value ? 'no_value' : 'no_message_key_(status_update)', ...extras } }];
}

const caption = (m) => (m && m.caption && String(m.caption).trim() ? `: ${String(m.caption).trim()}` : '');
let text = '';
switch (message.type) {
  case 'text': text = message.text?.body || ''; break;
  case 'button': text = message.button?.text || message.button?.payload || ''; break;
  case 'interactive': {
    const i = message.interactive || {};
    text = i.button_reply?.title || i.list_reply?.title || '';
    break;
  }
  case 'image': text = `[Sent a photo${caption(message.image)}]`; break;
  case 'video': text = `[Sent a video${caption(message.video)}]`; break;
  case 'document': {
    const d = message.document || {};
    text = `[Sent a document${d.filename ? ` (${d.filename})` : ''}${caption(d)}]`;
    break;
  }
  case 'audio': text = message.audio?.voice ? '[Sent a voice message]' : '[Sent an audio file]'; break;
  case 'sticker': text = '[Sent a sticker]'; break;
  case 'location': {
    const l = message.location || {};
    const place = [l.name, l.address].filter(Boolean).join(', ');
    text = `[Shared a location${place ? `: ${place}` : ''}${l.latitude != null ? ` (${l.latitude}, ${l.longitude})` : ''}]`;
    break;
  }
  case 'contacts': text = '[Shared a contact card]'; break;
  case 'reaction': return [{ json: { skip: true, reason: 'reaction', ...extras } }];
  default: text = `[Sent a ${message.type || 'message'} that can't be opened here]`;
}
text = String(text).trim();
if (!text) {
  return [{ json: { skip: true, reason: 'empty_message', message_type: message.type, ...extras } }];
}

return [{ json: {
  ...extras,
  skip: false,
  phone_number_id: value.metadata?.phone_number_id || '',
  from_wa_id: message.from || '',
  contact_name: value.contacts?.[0]?.profile?.name || null,
  wa_message_id: message.id || '',
  message_type: message.type,
  message_timestamp: message.timestamp ? new Date(Number(message.timestamp) * 1000).toISOString() : new Date().toISOString(),
  body: text.slice(0, 4000)
} }];

