-- Meta sometimes delivers the same message twice. Only the first copy
-- goes on to Elliot, so the client never gets two answers (0032).
select claim_whatsapp_message($1, $2) as is_new;

parameters.jsCode:
// Hands the message to Elliot (workflow 01, the same agent as the website
// chat), so WhatsApp gets the same answers: listings, viewings booked with
// the property, lead capture, hand-over to the team.
//
// Elliot's address: by default worked out from this n8n's own address
// (https://<you>.app.n8n.cloud/webhook/chat). To use another one, paste it
// below instead of the placeholder, or set an ELLIOT_CHAT_WEBHOOK_URL variable.
const ELLIOT_CHAT_WEBHOOK_URL = 'PASTE_ELLIOT_CHAT_WEBHOOK_URL_HERE';

function setting(name, pasted) {
  try { if ($vars && $vars[name]) return String($vars[name]); } catch (e) {}
  try { if ($env && $env[name]) return String($env[name]); } catch (e) {}
  return String(pasted || '').startsWith('PASTE_') ? '' : String(pasted || '');
}

const f = $('Extract WhatsApp Fields').first().json;
const tenant = $('Lookup Tenant by Phone Number Id').first().json;
const contact = $('Upsert Contact').first().json || {};
const conversationId = $input.first().json.id;

let url = setting('ELLIOT_CHAT_WEBHOOK_URL', ELLIOT_CHAT_WEBHOOK_URL);
if (!url) {
  let resume = '';
  try { resume = String($execution.resumeUrl || ''); } catch (e) {}
  const at = resume.indexOf('/webhook-waiting/');
  if (at > 0) url = resume.slice(0, at) + '/webhook/chat';
}
if (!url) {
  throw new Error("Can't work out Elliot's address: paste the chat webhook URL (workflow 01's Production URL) into ELLIOT_CHAT_WEBHOOK_URL in this node.");
}

// 0047: Elliot's own workflows use the secret-protected address, which is the
// only one allowed to say "this is email / WhatsApp from this client".
url = String(url || '').replace(/\/chat\/?(\?.*)?$/, '/chat-internal');

return [{ json: {
  chat_url: url,
  request: {
    tenant_slug: tenant.tenant_slug,
    message: f.body,
    conversation_id: conversationId,
    channel: 'whatsapp',
    contact: { name: contact.name || null, phone: contact.phone || ('+' + f.from_wa_id) }
  }
} }];

// What Elliot (workflow 01) answered. 01 replies { reply } normally, or
// { reply: null, human: true } when a team member has taken the chat over
// (then nothing is sent: the person answers from the dashboard).
// If Elliot failed, the client still gets a short holding message and the
// failure is logged, so nobody is left without an answer.
const FALLBACK = "Sorry, I can't answer that right now. Someone from our team will get back to you shortly.";
const r = $input.first().json;
const status = Number(r.statusCode || 0);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
const req = $('Build Elliot Request').first().json.request;
const base = { conversation_id: req.conversation_id, tenant_slug: req.tenant_slug };

if (!(status >= 200 && status < 300) || !body || typeof body !== 'object') {
  return [{ json: { ...base, reply: FALLBACK, human: false, elliot_error: `Elliot answered with HTTP ${status || 'no response'}` } }];
}
if (body.human === true) {
  return [{ json: { ...base, reply: '', human: true, elliot_error: null } }];
}
const reply = String(body.reply || '').trim();
return [{ json: { ...base, reply: reply || FALLBACK, human: false, elliot_error: reply ? null : 'Elliot returned an empty reply' } }];

// Elliot writes for the website chat, which shows Markdown. WhatsApp doesn't:
// bold is *single asterisks*, there are no [text](link) links or headings,
// and a message can be at most 4096 characters.
function toWhatsApp(text) {
  let t = String(text || '').replace(/\r\n/g, '\n');
  t = t.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (m, label, url) => (label.trim() === url ? url : `${label.trim()}: ${url}`));
  t = t.replace(/\*\*(.+?)\*\*/g, '*$1*');
  t = t.replace(/__(.+?)__/g, '_$1_');
  t = t.replace(/^#{1,6}\s+/gm, '');
  t = t.replace(/^(\s*)[-*]\s+/gm, '$1• ');
  t = t.replace(/\n{3,}/g, '\n\n').trim();
  if (t.length > 4096) t = t.slice(0, 4093).trimEnd() + '...';
  return t;
}

const f = $('Extract WhatsApp Fields').first().json;
const tenant = $('Lookup Tenant by Phone Number Id').first().json;
const answer = $input.first().json;
return [{ json: {
  tenant_id: tenant.tenant_id,
  conversation_id: answer.conversation_id,
  phone_number_id: f.phone_number_id || tenant.whatsapp_phone_number_id,
  to: f.from_wa_id,
  text: toWhatsApp(answer.reply)
} }];

// Meta answers { messages: [{ id }] } when it accepted the message, or
// { error: { message, code } } when it didn't (expired token, number not
// verified, 24-hour window closed -- code 131047, etc.).
const r = $input.first().json;
const status = Number(r.statusCode || 0);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
const apiError = body && typeof body === 'object' ? body.error : null;
const ok = status >= 200 && status < 300 && !apiError;
const sent = $('Format for WhatsApp').first().json;
let error = null;
if (!ok) {
  error = apiError
    ? `${apiError.message || 'Meta refused the message'}${apiError.code ? ` (code ${apiError.code})` : ''}`
    : `WhatsApp API answered with HTTP ${status || 'no response'}`;
}
return [{ json: {
  ok,
  error,
  status,
  tenant_id: sent.tenant_id,
  conversation_id: sent.conversation_id,
  to: sent.to,
  wa_message_id: (body && body.messages && body.messages[0] && body.messages[0].id) || null
} }];

parameters.query:
-- An audit_log row, and a note in the conversation so the team sees the
-- client didn't get the answer (0032).
select log_whatsapp_send_failure($1, $2::uuid, $3, $4::jsonb);

-- 0048: audit log (alerts) and a note in the client's conversation. Meta
-- repeats status updates; each failed message is recorded once.
select record_whatsapp_delivery_failure($1, $2, $3, $4) as recorded;
